function n(e){return{id:e.id!=null?Number(e.id):void 0,line_no:e.line_no!=null?Number(e.line_no):void 0,item_id:e.item_id!=null?Number(e.item_id):void 0,item_code:e.item_code!=null?String(e.item_code):void 0,item_name:e.item_name!=null?String(e.item_name):void 0,requirement:e.requirement!=null?String(e.requirement):void 0,is_done:!!e.is_done,remark:e.remark!=null?String(e.remark):void 0}}function m(e){return e?.length?e.map(i=>n(i)):[]}function t(e){return{line_no:e.line_no??1,item_id:e.item_id,item_code:e.item_code,item_name:e.item_name,requirement:e.requirement,is_done:e.is_done??!1,remark:e.remark}}export{m,t};
